import { Component } from '@angular/core'

type Item = { name: string; price: number; qty: number }

@Component({
  selector: 'app-cart',
  standalone: true,
  template: `
    <ul>
      @for (item of items; track item.name) {
        <li>
          {{ item.name }} x {{ item.qty }}
          <button (click)="add(item.name)">+</button>
          <button (click)="remove(item.name)">-</button>
        </li>
      }
    </ul>
    <p>Total: {{ total }}</p>
  `,
})
export class CartComponent {
  items: Item[] = [
    { name: 'Tea', price: 400, qty: 1 },
    { name: 'Cake', price: 550, qty: 0 },
  ]
  total = 400

  add(name: string) {
    this.items = this.items.map((item) =>
      item.name === name ? { ...item, qty: item.qty + 1 } : item,
    )
    this.recalc()
  }

  remove(name: string) {
    this.items = this.items.map((item) =>
      item.name === name ? { ...item, qty: Math.max(0, item.qty - 1) } : item,
    )
  }

  private recalc() {
    this.total = this.items.reduce((sum, item) => sum + item.price * item.qty, 0)
  }
}

